104	export function getPlanTier(planName: string): PlanTier {
105	  if (planName === PLAN_STARTER_MONTHLY || planName === PLAN_STARTER_ANNUAL)
106	    return "starter";
107	  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
108	    return "pro";
109	  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
110	    return "ultimate";
111	  return "free";
112	}
