1	import { useState, useCallback, useEffect } from "react";
2	import type {
3	  ActionFunctionArgs,
4	  HeadersFunction,
5	  LoaderFunctionArgs,
6	} from "react-router";
7	import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
8	import { useAppBridge } from "@shopify/app-bridge-react";
9	import { authenticate } from "../shopify.server";
10	import { boundary } from "@shopify/shopify-app-react-router/server";
11	import db from "../db.server";
12	import { getShopSubscription } from "../billing.server";
13	import { PLAN_LIMITS, UNLIMITED } from "../plans";
14	import {
15	  Page,
16	  Layout,
17	  Card,
18	  BlockStack,
19	  InlineStack,
20	  InlineGrid,
21	  Text,
22	  Badge,
23	  Button,
24	  TextField,
25	  Select,
26	  Modal,
27	  IndexTable,
28	  useIndexResourceState,
29	  EmptyState,
30	  Divider,
31	  Box,
32	  Tooltip,
33	  Checkbox,
34	  Banner,
35	} from "@shopify/polaris";
36	import { PlusIcon, DeleteIcon, EditIcon, ViewIcon, HideIcon } from "@shopify/polaris-icons";
37	
38	const DAYS_OPTIONS = [
39	  { label: "Monday", value: "Mon" },
40	  { label: "Tuesday", value: "Tue" },
41	  { label: "Wednesday", value: "Wed" },
42	  { label: "Thursday", value: "Thu" },
43	  { label: "Friday", value: "Fri" },
44	  { label: "Saturday", value: "Sat" },
45	  { label: "Sunday", value: "Sun" },
46	];
47	
48	export const loader = async ({ request }: LoaderFunctionArgs) => {
49	  const { session } = await authenticate.admin(request);
50	  const shop = session.shop;
51	
52	  const [rules, zones, subscription] = await Promise.all([
53	    db.deliveryRule.findMany({
54	      where: { shop },
55	      orderBy: { priority: "asc" },
56	    }),
57	    db.zipCode.findMany({
58	      where: { shop, zone: { not: null } },
59	      select: { zone: true },
60	      distinct: ["zone"],
61	    }),
62	    getShopSubscription(shop),
63	  ]);
64	
65	  return {
66	    rules,
67	    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
68	    subscription,
69	  };
70	};
71	
72	export const action = async ({ request }: ActionFunctionArgs) => {
73	  const { session } = await authenticate.admin(request);
74	  const shop = session.shop;
75	  const formData = await request.formData();
76	  const intent = formData.get("intent");
77	
78	  if (intent === "create" || intent === "update") {
79	    const id = String(formData.get("id") || "");
80	    const name = String(formData.get("name") || "").trim();
81	    const zone = String(formData.get("zone") || "").trim() || null;
82	    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
83	    const minOrderAmount = formData.get("minOrderAmount")
84	      ? parseFloat(String(formData.get("minOrderAmount")))
85	      : null;
86	    const deliveryFee = formData.get("deliveryFee")
87	      ? parseFloat(String(formData.get("deliveryFee")))
88	      : null;
89	    const freeShippingAbove = formData.get("freeShippingAbove")
90	      ? parseFloat(String(formData.get("freeShippingAbove")))
91	      : null;
92	    const estimatedDays =
93	      String(formData.get("estimatedDays") || "").trim() || null;
94	    const cutoffTime =
95	      String(formData.get("cutoffTime") || "").trim() || null;
96	    const daysOfWeek =
97	      String(formData.get("daysOfWeek") || "").trim() || null;
98	    const priority = parseInt(String(formData.get("priority") || "0"), 10);
99	
100	    if (!name) return { error: "Rule name is required." };
101	
102	    const data = {
103	      name,
104	      zone,
105	      zipCodes,
106	      minOrderAmount,
107	      deliveryFee,
108	      freeShippingAbove,
109	      estimatedDays,
110	      cutoffTime,
111	      daysOfWeek,
112	      priority,
113	    };
114	
115	    if (intent === "update" && id) {
116	      try {
117	        const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
118	        if (!existing) return { error: "Rule not found." };
119	        await db.deliveryRule.update({ where: { id }, data });
120	        return { success: true, action: "updated" };
121	      } catch {
122	        return { error: "Failed to update rule." };
123	      }
124	    } else {
125	      // Plan-gating: check limits before creating a new rule
126	      const subscription = await getShopSubscription(shop);
127	      const { maxDeliveryRules, label: planLabel } = subscription.limits;
128	
129	      if (maxDeliveryRules === 0) {
130	        return {
131	          error:
132	            "Delivery rules are not available on the Free plan. Upgrade to Starter or Pro.",
133	        };
134	      }
135	
136	      if (maxDeliveryRules < UNLIMITED) {
137	        const currentCount = await db.deliveryRule.count({ where: { shop } });
138	        if (currentCount >= maxDeliveryRules) {
139	          return {
140	            error: `You've reached the ${maxDeliveryRules} delivery rule limit on the ${planLabel} plan. Upgrade to Pro for unlimited rules.`,
141	          };
142	        }
143	      }
144	
145	      await db.deliveryRule.create({ data: { shop, ...data } });
146	      return { success: true, action: "created" };
147	    }
148	  }
149	
150	  if (intent === "delete") {
151	    const id = String(formData.get("id"));
152	    try {
153	      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
154	      if (!existing) return { error: "Rule not found." };
155	      await db.deliveryRule.delete({ where: { id } });
156	      return { success: true, action: "deleted" };
157	    } catch {
158	      return { error: "Failed to delete rule." };
159	    }
160	  }
161	
162	  if (intent === "toggle") {
163	    const id = String(formData.get("id"));
164	    const isActive = formData.get("isActive") === "true";
165	    try {
166	      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
167	      if (!existing) return { error: "Rule not found." };
168	      await db.deliveryRule.update({
169	        where: { id },
170	        data: { isActive: !isActive },
171	      });
172	      return { success: true, action: "toggled" };
173	    } catch {
174	      return { error: "Failed to toggle rule." };
175	    }
176	  }
177	
178	  if (intent === "bulk-delete") {
179	    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
180	    if (ids.length === 0) return { error: "No rules selected." };
181	    try {
182	      await db.deliveryRule.deleteMany({ where: { id: { in: ids }, shop } });
183	      return { success: true, action: "bulk-deleted" };
184	    } catch {
185	      return { error: "Failed to delete rules." };
186	    }
187	  }
188	
189	  if (intent === "bulk-toggle") {
190	    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
191	    const active = formData.get("active") === "true";
192	    if (ids.length === 0) return { error: "No rules selected." };
193	    try {
194	      await db.deliveryRule.updateMany({
195	        where: { id: { in: ids }, shop },
196	        data: { isActive: active },
197	      });
198	      return { success: true, action: active ? "bulk-activated" : "bulk-deactivated" };
199	    } catch {
200	      return { error: "Failed to update rules." };
201	    }
202	  }
203	
204	  return null;
205	};
