1	import type { ActionFunctionArgs } from "react-router";
2	import { authenticate } from "../shopify.server";
3	import db from "../db.server";
4	
5	export const action = async ({ request }: ActionFunctionArgs) => {
6	  const { shop } = await authenticate.webhook(request);
7	
8	  // Webhook requests can trigger multiple times and after an app has already been uninstalled.
9	  // Delete all shop data immediately on uninstall (Shopify App Store requirement).
10	  // The shop/redact GDPR webhook fires 48 hours later and also runs this cleanup.
11	  if (shop) {
12	    try {
13	      // Delete FeatureVotes first (FK constraint to FeatureRequest)
14	      await db.featureVote.deleteMany({ where: { shop } });
15	      await Promise.all([
16	        db.session.deleteMany({ where: { shop } }),
17	        db.zipCode.deleteMany({ where: { shop } }),
18	        db.deliveryRule.deleteMany({ where: { shop } }),
19	        db.waitlistEntry.deleteMany({ where: { shop } }),
20	        db.widgetConfig.deleteMany({ where: { shop } }),
21	        db.subscription.deleteMany({ where: { shop } }),
22	        db.shopSettings.deleteMany({ where: { shop } }),
23	        db.featureRequest.deleteMany({ where: { shop } }),
24	      ]);
25	    } catch {
26	      // Log failures silently — Shopify requires a 200 response regardless
27	    }
28	  }
29	
30	  return new Response();
31	};
